import sys, re, unicodedata; sys.path.insert(0, '/home/claude/winesite/scripts/fr_a')
from common import S, dump

def slug(s):
    s = unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode().lower()
    return re.sub(r'[^a-z0-9]+', '-', s).strip('-')

sites = []
def add(key, name, kind, cls, app, text, producers=None, **kw):
    sites.append(S(slug(name), key, name, kind, cls, app, text, producers, **kw))

C55 = "(1855)"
# ---------------- 1855 Médoc (plus Haut-Brion) ----------------
M = [
("lafite-rothschild", "Château Lafite Rothschild", "Premier Cru Classé " + C55, "Pauillac",
 "Listed first among the first growths in 1855, Lafite sits on the northern edge of Pauillac, its vines running down to the Jalle du Breuil stream that separates it from Cos d'Estournel in Saint-Estèphe. The Marquis Nicolas-Alexandre de Ségur made it famous in the eighteenth century; Baron James de Rothschild bought it in 1868 and died three months later, and his descendants still own it. The style is the most perfumed of the Pauillac firsts: cedar, graphite and violets over a fine-grained frame. Its second wine is Carruades de Lafite."),
("latour", "Château Latour", "Premier Cru Classé " + C55, "Pauillac",
 "Latour takes its name from a fourteenth-century fort that guarded the estuary; the domed tower in the vines is a later dovecote. The heart of the estate is the 47-ha Enclos around the château, deep gravel sloping to the riverside meadows that blunt frost and cool hot nights. Latour is the most powerful and slowest-maturing of the first growths, famous for consistency in poor vintages. François Pinault's Artémis group has owned it since 1993, and in 2012 Latour left the en primeur system to release wines only when it judges them ready."),
("margaux", "Château Margaux", "Premier Cru Classé " + C55, "Margaux",
 "The only first growth in the Margaux appellation, and the only one whose château is a true neoclassical palace: Louis Combes built it between 1810 and 1816, columns and all. The Mentzelopoulos family bought the estate in 1977 and, with director Paul Pontallier, restored its reputation after a weak spell. The wine is the archetype of Margaux perfume, violets and red fruit over silky tannins. Its Pavillon Blanc, pure Sauvignon Blanc, is sold as Bordeaux because the appellation is red-only. Norman Foster designed the new cellars, opened in 2015."),
("haut-brion", "Château Haut-Brion", "Premier Cru Classé " + C55 + "; Cru Classé de Graves (red, and white from 1960)", "Pessac-Léognan",
 "The only red outside the Médoc ranked in 1855, and arguably the first estate wine sold by name: Arnaud III de Pontac shipped 'Ho Bryan' to London, where Samuel Pepys drank it in 1663. The vineyard sits on a deep gravel ridge in Pessac, now surrounded by the city. American banker Clarence Dillon bought it in 1935; his descendant Prince Robert of Luxembourg runs it. The red is smoky and tobacco-scented; the white, rare and expensive, ages for decades."),
("mouton-rothschild", "Château Mouton Rothschild", "Premier Cru Classé (1973; Deuxième Cru in 1855)", "Pauillac",
 "The only estate ever promoted in the 1855 classification. Ranked first among the seconds in 1855, two years after Baron Nathaniel de Rothschild bought it, Mouton was raised to first growth in 1973 after half a century of lobbying by Baron Philippe de Rothschild, who also pioneered château bottling in 1924. Its motto changed from 'Premier ne puis, second ne daigne, Mouton suis' to 'Premier je suis, second je fus, Mouton ne change'. Every vintage since 1945 carries a label by an artist, from Braque and Picasso to Bacon and Warhol."),
("rauzan-segla", "Château Rauzan-Ségla", "Deuxième Cru Classé " + C55, "Margaux",
 "Pierre de Rauzan created this estate in 1661, and it was split in the eighteenth century into Rauzan-Ségla and Rauzan-Gassies. In 1855 Rauzan-Ségla headed the second growths, just behind Mouton. After a long slump, the Wertheimer family (owners of Chanel) bought it in 1994 and invested heavily in drainage and replanting; it is now one of the finest Margaux, perfumed and silky with real depth."),
("rauzan-gassies", "Château Rauzan-Gassies", "Deuxième Cru Classé " + C55, "Margaux",
 "The other half of Pierre de Rauzan's seventeenth-century estate, owned by the Quié family since 1946. Its parcels interlock with Rauzan-Ségla on the gravel around Margaux village. The wine has improved markedly since the 2000s, with more precision and freshness than its old reputation suggests."),
("leoville-las-cases", "Château Léoville Las Cases", "Deuxième Cru Classé " + C55, "Saint-Julien",
 "The largest share of the old Léoville estate, which was divided after the Revolution into Las Cases, Poyferré and Barton. Its walled Grand Clos, entered through a stone gateway with a lion on top (the label's emblem), runs right up to Latour's vineyards. Under the Delon family, especially Michel Delon from the 1970s, it became the archetypal 'super second', with Pauillac-like density and prices to match. Clos du Marquis is a separate wine, not a second wine.",
 None),
("leoville-poyferre", "Château Léoville Poyferré", "Deuxième Cru Classé " + C55, "Saint-Julien",
 "Named after Baron Jean-Marie de Poyferré, who inherited this third of the Léoville estate in the early nineteenth century. The Cuvelier family has owned it since 1920; Didier Cuvelier's modernisation from 1979 made it one of Saint-Julien's richest, most plush wines. Its château faces Las Cases across the road in the village of Saint-Julien."),
("leoville-barton", "Château Léoville Barton", "Deuxième Cru Classé " + C55, "Saint-Julien",
 "Hugh Barton, of an Irish family of Bordeaux merchants, bought a third of the Léoville vineyard in 1826, five years after buying Langoa. There is no Léoville Barton château: the wine is made in the cellars of Langoa. Anthony Barton, who ran both estates from 1983 until his death in 2022, kept prices fair through the boom years, and his daughter Lilian Barton Sartorius continues the line. The wine is classic, firm, cedary Saint-Julien that rewards patience."),
("durfort-vivens", "Château Durfort-Vivens", "Deuxième Cru Classé " + C55, "Margaux",
 "Named after the Durfort de Duras family, who owned it from the fourteenth century. The Lurton family took it over in 1961, and Gonzague Lurton converted it to biodynamics in the 2010s; it now experiments with amphorae and bottlings of single Cabernet parcels. The wine is one of the more Cabernet-driven, mineral Margaux."),
("gruaud-larose", "Château Gruaud Larose", "Deuxième Cru Classé " + C55, "Saint-Julien",
 "Founded in the 1720s by the abbé Gruaud and later passed to his heir, Monsieur de La Rose, it is one of the largest estates in Saint-Julien, set inland on a broad gravel plateau. The Merlaut family has owned it since 1997. Gruaud makes dense, long-lived wine, a little more rustic and broad-shouldered than the riverside Saint-Juliens."),
("lascombes", "Château Lascombes", "Deuxième Cru Classé " + C55, "Margaux",
 "Named after Antoine de Lascombes, a seventeenth-century owner. The American writer and merchant Alexis Lichine bought it in 1952 and expanded it to over 100 ha, making it one of the largest Margaux estates. A large share of Merlot on clay-rich parcels gives it a riper, rounder style than most Margaux."),
("brane-cantenac", "Château Brane-Cantenac", "Deuxième Cru Classé " + C55, "Margaux",
 "Baron Hector de Brane, nicknamed the 'Napoleon of the vines', sold Brane-Mouton (now Mouton Rothschild) in 1830 to concentrate on his estate in Cantenac. The Lurton family has owned it since 1925, and Henri Lurton has run it since 1992. Its central gravel plateau gives one of the most fragrant and refined Margaux."),
("pichon-baron", "Château Pichon Baron", "Deuxième Cru Classé " + C55, "Pauillac",
 "In 1850 the Pichon-Longueville estate was divided between Baron Raoul de Pichon-Longueville and his sisters; the baron kept this half and built the turreted fairytale château in 1851. AXA Millésimes bought it in 1987 and, under Christian Seely, restored its reputation. The wine is dense, structured Pauillac, the vineyard facing Latour across the D2 road."),
("pichon-comtesse", "Château Pichon Longueville Comtesse de Lalande", "Deuxième Cru Classé " + C55, "Pauillac",
 "The sisters' share of the 1850 Pichon division, named after Virginie, Comtesse de Lalande. May-Eliane de Lencquesaing ran it from 1978 to 2007, when she sold it to Champagne Louis Roederer. Some of its vines lie across the border in Saint-Julien, and a relatively high share of Merlot gives a famously silky, perfumed style for Pauillac."),
("ducru-beaucaillou", "Château Ducru-Beaucaillou", "Deuxième Cru Classé " + C55, "Saint-Julien",
 "The name means Ducru (a nineteenth-century owner) plus 'beaux cailloux', beautiful stones, for the large gravel that covers its riverside vineyard. The Borie family has owned it since 1941; Bruno Borie runs it. The château, with its Victorian towers, faces the Gironde, and the wine is the most refined and polished of the Saint-Julien seconds."),
("cos-d-estournel", "Château Cos d'Estournel", "Deuxième Cru Classé " + C55, "Saint-Estèphe",
 "Louis-Gaspard d'Estournel, who traded horses and wine with India, built the extraordinary chai with pagoda towers and a carved door from Zanzibar in the 1830s. Nicknamed the 'Maharajah of Saint-Estèphe', he died in debt. Cos faces Lafite across the Jalle du Breuil, on a gravel ridge facing south-east. Owned by Michel Reybier since 2000, it makes rich, exotic, spicy Saint-Estèphe from gravity-fed cellars rebuilt in 2008."),
("montrose", "Château Montrose", "Deuxième Cru Classé " + C55, "Saint-Estèphe",
 "Montrose did not exist as a vineyard until the early nineteenth century, when Étienne Théodore Dumoulin cleared a heath of pink heather on a gravel mound above the estuary. Fifty years later it was a second growth. The estuary breeze and gravel over clay give one of the most powerful, long-lived wines of the Médoc. Martin and Olivier Bouygues bought it in 2006 and rebuilt it with a strong environmental focus, including solar panels and geothermal energy."),
("kirwan", "Château Kirwan", "Troisième Cru Classé " + C55, "Margaux",
 "Named after Mark Kirwan, an Irishman from Galway who married into the estate in the eighteenth century. The Schÿler family, Bordeaux négociants of German origin, have owned it since 1925, and their botanical gardens around the château are listed. Kirwan was named first of the third growths in 1855; its Cantenac vineyard gives supple, aromatic wine."),
("d-issan", "Château d'Issan", "Troisième Cru Classé " + C55, "Margaux",
 "A moated seventeenth-century château built on the foundations of the medieval Château de la Mothe-Cantenac, beside the estuary meadows. Its motto, 'Regum mensis arisque deorum' (for the tables of kings and the altars of the gods), appears on the gate. The Cruse family has owned it since 1945 and was joined by Jacques Thienpont in 2013. The wine is classic, elegant Margaux."),
("lagrange", "Château Lagrange", "Troisième Cru Classé " + C55, "Saint-Julien",
 "The largest estate in Saint-Julien, inland on two gravel hills behind Gruaud Larose, with an Italianate tower. Japan's Suntory bought it in 1983, the first Japanese investment in a classed growth, and replanted most of the vineyard. It makes firm, good-value Saint-Julien and a white wine, Les Arums de Lagrange, sold as Bordeaux."),
("langoa-barton", "Château Langoa Barton", "Troisième Cru Classé " + C55, "Saint-Julien",
 "Bought by Hugh Barton in 1821, Langoa is the oldest classed growth to have remained with the same family, now the seventh and eighth Barton generations. Its eighteenth-century chartreuse houses the family and the cellars for both Langoa and Léoville Barton. The wine is a slightly softer, earlier-drinking cousin of Léoville."),
("giscours", "Château Giscours", "Troisième Cru Classé " + C55, "Margaux",
 "A large estate in Labarde with a grand Second Empire château and a park landscaped by Eugène Bühler. The Dutch Albada Jelgersma family has owned it since 1995 and also owns du Tertre. Giscours made famous wines in the 1970s, then slipped; it has steadily regained form with generous, dark-fruited Margaux."),
("malescot-st-exupery", "Château Malescot Saint-Exupéry", "Troisième Cru Classé " + C55, "Margaux",
 "Simon Malescot, counsellor to King Louis XIV, bought the estate in 1697; Count Jean-Baptiste de Saint-Exupéry, an ancestor of the author of *The Little Prince*, owned it in the nineteenth century. The Zuger family has run it since 1955. Its château stands in the middle of Margaux village, and the wine is deep and spicy, among the most concentrated in the appellation."),
("boyd-cantenac", "Château Boyd-Cantenac", "Troisième Cru Classé " + C55, "Margaux",
 "Named after Jacques Boyd, of an Irish family, who bought vines in Cantenac in the 1750s. Owned by the Guillemet family, who also make Château Pouget in the same cellars. A small estate making traditional, firm Margaux with a good share of Cabernet."),
("cantenac-brown", "Château Cantenac Brown", "Troisième Cru Classé " + C55, "Margaux",
 "John Lewis Brown, of a Scottish family and father of the animal painter of the same name, built the château in the 1830s in an English Tudor style that looks nothing like any other building in the Médoc. Its vineyard lies on gravel in Cantenac, giving firm, deep-coloured wine. A new low-carbon winery, built with traditional materials such as rammed earth, opened in the 2020s."),
("palmer", "Château Palmer", "Troisième Cru Classé " + C55, "Margaux",
 "Major-General Charles Palmer, a British officer who fought under Wellington, bought the estate in 1814 and ruined himself on it; the Pereire banking brothers took it over in 1853. Today owned by the Sichel and Mähler-Besse families, Palmer consistently sells above many second growths. Farmed biodynamically since 2014, it uses a high share of Merlot (often 40% or more), which gives a sensual, velvety style. Its *Historical XIXth Century Wine* blends Margaux with northern Rhône Syrah, as merchants did when 'hermitaging' claret."),
("la-lagune", "Château La Lagune", "Troisième Cru Classé " + C55, "Haut-Médoc",
 "The first classed growth heading north from Bordeaux, in Ludon on sandy gravel close to the estuary. Its eighteenth-century chartreuse is attributed to the architect Victor Louis. The Frey family (also owners of Paul Jaboulet Aîné and Château Corton C) has owned it since 2000, with Caroline Frey making the wine and converting to biodynamics. The style is supple and perfumed."),
("desmirail", "Château Desmirail", "Troisième Cru Classé " + C55, "Margaux",
 "Named after Jean Desmirail, who married into the Rauzan family in the eighteenth century. Its vines were absorbed into Palmer and other estates in the twentieth century, and the name survived only as a brand until Lucien Lurton revived it in 1981. His son Denis Lurton now runs a small estate making elegant Margaux."),
("calon-segur", "Château Calon-Ségur", "Troisième Cru Classé " + C55, "Saint-Estèphe",
 "The most northerly classed growth, once owned by the Marquis de Ségur, who also owned Lafite and Latour but said his heart was at Calon: hence the heart on the label, a favourite Valentine's Day wine. The vineyard is largely walled. Since 2012, new owners have replanted and rebuilt the cellars, and the wine has become one of Saint-Estèphe's best, with a high share of Cabernet Sauvignon."),
("ferriere", "Château Ferrière", "Troisième Cru Classé " + C55, "Margaux",
 "One of the smallest classed growths, at under 25 ha, named after Gabriel Ferrière, a royal shipbroker. Leased to Château Lascombes for decades, it was revived by the Villars-Merlaut family in 1992 and is now run by Claire Villars-Lurton, who converted it to biodynamics. The wine is fine-boned and floral."),
("marquis-d-alesme", "Château Marquis d'Alesme", "Troisième Cru Classé " + C55, "Margaux",
 "Formerly Marquis d'Alesme Becker, this small estate in Margaux village was bought by the Perrodo family (also owners of Labégorce) in 2006. They dropped 'Becker' from the name in 2009 and built a new winery with Chinese-inspired gardens, a nod to Hubert Perrodo's Asian business links."),
("saint-pierre", "Château Saint-Pierre", "Quatrième Cru Classé " + C55, "Saint-Julien",
 "A small Saint-Julien estate bought in 1982 by Henri Martin, mayor of Saint-Julien and creator of Château Gloria, and now run by his descendants, the Triaud family. Its vines are scattered parcels of excellent gravel in the village, and the wine is plush and generous for Saint-Julien."),
("talbot", "Château Talbot", "Quatrième Cru Classé " + C55, "Saint-Julien",
 "Named after John Talbot, Earl of Shrewsbury, the English commander killed at Castillon in 1453, though there is no proof he ever owned it. The Cordier family has owned Talbot since 1917 and now runs it with the Rustmann and Bignon families. A large inland estate, it makes sturdy, savoury red and a well-known white, Caillou Blanc, sold as Bordeaux."),
("branaire-ducru", "Château Branaire-Ducru", "Quatrième Cru Classé " + C55, "Saint-Julien",
 "Facing Beychevelle across the road, Branaire takes its name from Jean-Baptiste Braneyre, who bought it in 1680, and from the Ducru family of the nineteenth century. The Maroteaux family has owned it since 1988 and built one of the first gravity-flow cellars in the Médoc in 1991. The wine is elegant, mid-weight Saint-Julien of real charm."),
("duhart-milon", "Château Duhart-Milon", "Quatrième Cru Classé " + C55, "Pauillac",
 "Bought by the Rothschilds of Lafite in 1962, Duhart-Milon's vines lie on the slopes of the Carruades plateau west of Lafite, next to the hamlet of Milon. The name recalls a legendary eighteenth-century pirate, Monsieur Duhart, said to have lived in Pauillac; it is a story more than a fact. The wine is a firmer, more affordable sibling of Lafite."),
("pouget", "Château Pouget", "Quatrième Cru Classé " + C55, "Margaux",
 "One of the smallest classed growths, about 10 ha in Cantenac, owned by the Guillemet family and made alongside Boyd-Cantenac. It makes traditional, firm Margaux at modest prices."),
("la-tour-carnet", "Château La Tour Carnet", "Quatrième Cru Classé " + C55, "Haut-Médoc",
 "A genuine medieval castle with a moat and a thirteenth-century keep, in Saint-Laurent-Médoc. Bernard Magrez bought it in 2000 and changed it radically, with heavy investment in the vineyard and a ripe, modern style. Its name comes from Jean de Foix's squire, Carnet, who won it by defending it in the Hundred Years War, according to tradition."),
("lafon-rochet", "Château Lafon-Rochet", "Quatrième Cru Classé " + C55, "Saint-Estèphe",
 "Instantly recognisable by its yellow château and label, painted that colour by the Tesseron family, who owned it from 1960 until 2021, when Jacky Lorenzetti (owner of Pédesclaux) bought it. The vineyard is next to Cos d'Estournel and Lafite, and the wine is firm, fresh Saint-Estèphe."),
("beychevelle", "Château Beychevelle", "Quatrième Cru Classé " + C55, "Saint-Julien",
 "Its name is said to derive from *baisse-voile*, lower the sail: ships on the Gironde dipped their sails to salute the Duc d'Épernon, admiral of France, who owned the estate in the seventeenth century. Hence the ship on the label. The eighteenth-century château is among the most elegant in the Médoc. Owned since the 1980s by a partnership led by Castel and Suntory, Beychevelle makes supple, aromatic Saint-Julien that often outperforms its rank."),
("prieure-lichine", "Château Prieuré-Lichine", "Quatrième Cru Classé " + C55, "Margaux",
 "Once the priory of the Benedictine monks of Cantenac, it was bought in 1951 by Alexis Lichine, the Russian-born wine writer and merchant, who added his name and opened it to visitors when such hospitality was unheard of in the Médoc. The vineyard is a patchwork of parcels across Margaux's five communes, giving a blended picture of the appellation."),
("marquis-de-terme", "Château Marquis de Terme", "Quatrième Cru Classé " + C55, "Margaux",
 "Named after the Marquis de Terme, who acquired it by marriage in 1762. The Sénéclauze family has owned it since 1935. A mid-sized estate in Margaux village whose wine has gained finesse since the 2010s."),
("pontet-canet", "Château Pontet-Canet", "Cinquième Cru Classé " + C55, "Pauillac",
 "Owned by the Tesseron family since 1975, Pontet-Canet became the most talked-about fifth growth of the 2000s. Alfred Tesseron converted to biodynamics, certified in 2010, brought back horses for ploughing, and introduced concrete amphorae made from the estate's own gravel. The wines, from vineyards next to Mouton, are now priced and scored like seconds."),
("batailley", "Château Batailley", "Cinquième Cru Classé " + C55, "Pauillac",
 "Its name recalls a battle of the Hundred Years War said to have been fought on the site. Owned by the Castéja family (of Borie-Manoux), it sits inland in a wooded park in south-western Pauillac. Batailley makes classic, firm, fairly priced Pauillac."),
("haut-batailley", "Château Haut-Batailley", "Cinquième Cru Classé " + C55, "Pauillac",
 "Split off from Batailley in 1942 when the Borie family divided its holdings, Haut-Batailley was run by the Bories of Ducru-Beaucaillou until the Cazes family of Lynch-Bages bought it in 2017. Its vines border Pichon Baron and Latour inland, and the wine is lighter-bodied and graceful."),
("grand-puy-lacoste", "Château Grand-Puy-Lacoste", "Cinquième Cru Classé " + C55, "Pauillac",
 "'Puy' means hill: the estate sits on a high gravel mound on the Bages plateau. The Borie family bought it in 1978, and Xavier Borie and now his daughter Emeline have made it a byword for classic, cassis-and-cedar Pauillac at a fair price."),
("grand-puy-ducasse", "Château Grand-Puy Ducasse", "Cinquième Cru Classé " + C55, "Pauillac",
 "Unusually, its château stands on the waterfront quay of Pauillac town, while its vines are scattered across three parts of the appellation. Named after Pierre Ducasse, an eighteenth-century lawyer. It makes approachable, mid-weight Pauillac."),
("lynch-bages", "Château Lynch-Bages", "Cinquième Cru Classé " + C55, "Pauillac",
 "Named after Thomas Lynch, of an Irish family, whose son Jean-Baptiste became mayor of Bordeaux. The Cazes family has owned it since 1939; Jean-Michel Cazes made it a 'poor man's Latour' famous for rich, cassis-laden wine, and restored the hamlet of Bages with a bakery and café. A new cellar designed by Chien Chung Pei opened in 2020."),
("lynch-moussas", "Château Lynch-Moussas", "Cinquième Cru Classé " + C55, "Pauillac",
 "The westernmost classed growth of Pauillac, on gravel at the edge of the forest. Like Lynch-Bages it was once owned by the Lynch family. The Castéja family has run it since 1919, replanting and expanding it from the 1970s."),
("dauzac", "Château Dauzac", "Cinquième Cru Classé " + C55, "Margaux",
 "In Labarde, close to the estuary, Dauzac has a famous place in wine science. In the early 1880s its manager Ernest David and the botanist Alexis Millardet noticed that vines sprayed with copper sulphate and lime, to deter grape thieves along the road, had escaped downy mildew. The result was *bouillie bordelaise*, the Bordeaux mixture that saved Europe's vineyards."),
("d-armailhac", "Château d'Armailhac", "Cinquième Cru Classé " + C55, "Pauillac",
 "Baron Philippe de Rothschild bought this neighbour of Mouton in 1933 and renamed it several times (Mouton Baron Philippe, then Mouton Baronne Philippe) before reverting in 1989 to the name of the eighteenth-century d'Armailhacq family. The wine has a relatively high share of Cabernet Franc and is softer than Mouton."),
("du-tertre", "Château du Tertre", "Cinquième Cru Classé " + C55, "Margaux",
 "'Tertre' means a small hill, and this estate in Arsac sits on one of the highest gravel ridges in the Margaux appellation. Owned by the Albada Jelgersma family since 1997, it uses a striking share of Cabernet Franc and some Petit Verdot, giving fragrant, fresh wines."),
("haut-bages-liberal", "Château Haut-Bages Libéral", "Cinquième Cru Classé " + C55, "Pauillac",
 "Named after the Libéral family, eighteenth-century merchants. Part of its vineyard borders Latour. Claire Villars-Lurton has converted it to biodynamics and agroforestry, planting hedges and trees among the vines."),
("pedesclaux", "Château Pédesclaux", "Cinquième Cru Classé " + C55, "Pauillac",
 "Founded by Pierre Urbain Pédesclaux, a Bordeaux wine broker of the early nineteenth century, when brokers (courtiers) were the men who drew up the 1855 ranking. Long underperforming, it was transformed after Jacky Lorenzetti bought it in 2009, with a glass-walled, gravity-fed cellar by architect Jean-Michel Wilmotte and replanted vineyards near Mouton and Pontet-Canet."),
("belgrave", "Château Belgrave", "Cinquième Cru Classé " + C55, "Haut-Médoc",
 "An inland estate in Saint-Laurent-Médoc, just behind Lagrange and the Saint-Julien border. Part of the Dourthe group since 1979, it makes firm, good-value Haut-Médoc from gravel over clay."),
("camensac", "Château de Camensac", "Cinquième Cru Classé " + C55, "Haut-Médoc",
 "An eighteenth-century chartreuse in Saint-Laurent-Médoc. The Merlaut family and associates have owned it since 2005 and worked to restore its gravel vineyard. The wine is supple and approachable for a classed growth."),
("cos-labory", "Château Cos Labory", "Cinquième Cru Classé " + C55, "Saint-Estèphe",
 "A small estate next door to Cos d'Estournel, owned by the Audoy family. Its wine is firm, honest Saint-Estèphe at a price well below its famous neighbour's."),
("clerc-milon", "Château Clerc Milon", "Cinquième Cru Classé " + C55, "Pauillac",
 "Bought by Baron Philippe de Rothschild in 1970, its vines lie next to Lafite and Mouton close to the estuary, around the hamlet of Milon. A new winery opened in 2011. The wine is richer and more Mouton-like than its rank suggests."),
("croizet-bages", "Château Croizet-Bages", "Cinquième Cru Classé " + C55, "Pauillac",
 "On the Bages plateau next to Lynch-Bages, owned by the Quié family (also of Rauzan-Gassies) since 1942. Long considered an underachiever, it has improved with recent investment."),
("cantemerle", "Château Cantemerle", "Cinquième Cru Classé (added September 1855)", "Haut-Médoc",
 "Missing from the original list of April 1855, Cantemerle was added a few months later at the bottom of the fifth growths after its owner, the widow Villeneuve-Durfort, produced records proving its prices. The château stands in a wooded park in Macau, at the southern end of the Médoc. The wine is perfumed and supple, from sandy gravel."),
]
for k, n, c, a, t, *p in M:
    add(k, n, "chateau", c, a, t)

# ---------------- 1855 Sauternes & Barsac ----------------
SB = [
("yquem", "Château d'Yquem", "Premier Cru Supérieur (1855)", "Sauternes",
 "The only wine given the rank of Premier Cru Supérieur in 1855, a title no red wine received. Yquem sits on the highest hill of Sauternes, about 75 m, with a fortified manor dating back to the fifteenth century. The Sauvage family owned it from 1593; in 1785 Françoise-Joséphine de Sauvage d'Yquem married Count Louis-Amédée de Lur-Saluces, and their descendants ran it until LVMH took control at the end of the 1990s, with Alexandre de Lur-Saluces leaving in 2004. Thomas Jefferson ordered it in the 1780s. About 100 ha are in production, roughly three quarters Sémillon. Pickers make up to ten or more tries, and in poor years (1992, 2012 among them) no Yquem is released. Its dry white, Ygrec (Y), first made in 1959, is now produced every year.",
 ["Château d'Yquem"]),
("la-tour-blanche", "Château La Tour Blanche", "Premier Cru Classé (1855)", "Sauternes",
 "Ranked first of the Premiers Crus after Yquem in 1855. In 1907 its owner, the philanthropist Daniel Iffla Osiris, left it to the French state on condition that it house a school of viticulture, and it still runs a wine college today. Its wines, from Bommes, are rich and barrel-fermented."),
("lafaurie-peyraguey", "Château Lafaurie-Peyraguey", "Premier Cru Classé (1855)", "Sauternes",
 "A thirteenth-century fortified manor in Bommes with crenellated walls. Swiss businessman Silvio Denz, owner of the glassmaker Lalique, bought it in 2014 and opened a hotel and restaurant, Lalique, where crystal and Sauternes meet. The wines are among the most consistent of the Premiers Crus."),
("clos-haut-peyraguey", "Clos Haut-Peyraguey", "Premier Cru Classé (1855)", "Sauternes",
 "Created when the Peyraguey estate was divided in 1879, this small vineyard on the summit of the Bommes hill was owned by the Pauly family for a century before Bernard Magrez bought it in 2012. The wines are fine and lifted rather than heavy."),
("rayne-vigneau", "Château de Rayne Vigneau", "Premier Cru Classé (1855)", "Sauternes",
 "On a hill in Bommes famous for its soil studded with semi-precious stones, agate, onyx and quartz brought by the Garonne, which a nineteenth-century owner had catalogued. The wine is fragrant and finely balanced."),
("suduiraut", "Château Suduiraut", "Premier Cru Classé (1855)", "Sauternes",
 "A grand seventeenth-century château in Preignac with gardens attributed to André Le Nôtre's school, bordering Yquem's vines. AXA Millésimes has owned it since 1992. Suduiraut is one of the richest, most opulent Sauternes; it also makes dry whites (Lions de Suduiraut and S de Suduiraut)."),
("coutet", "Château Coutet", "Premier Cru Classé (1855)", "Barsac",
 "The largest of the Barsac first growths, with a thirteenth-century tower that once served as an English fort. Owned by the Baly family since 1977, distributed with Baron Philippe de Rothschild SA. Its rare Cuvée Madame, made only in great years from the oldest vines, is one of the most sought-after Barsacs."),
("climens", "Château Climens", "Premier Cru Classé (1855)", "Barsac",
 "Often called the Lord of Barsac, Climens farms about 30 ha in one block on the highest point of the Barsac limestone plateau, planted entirely with Sémillon. Bérénice Lurton ran it from 1992 and converted it to biodynamics in 2010, the first Sauternais classed growth to do so. In 2022 she sold a majority stake to the Moitry family and stayed on as a consultant. The wine is a model of Barsac freshness and finesse."),
("guiraud", "Château Guiraud", "Premier Cru Classé (1855)", "Sauternes",
 "One of the largest estates of Sauternes, on gravel next to Yquem. Since 2006 it has belonged to a group including Robert Peugeot, Xavier Planty, Olivier Bernard of Domaine de Chevalier and Stephan von Neipperg, and it was the first Sauternes classed growth certified organic (2011). It runs a conservatory of old vine selections."),
("rieussec", "Château Rieussec", "Premier Cru Classé (1855)", "Sauternes",
 "In Fargues, on high gravel next to Yquem. The Rothschilds of Lafite (Domaines Barons de Rothschild) bought it in 1984. Rieussec is known for its deep golden colour and rich, honeyed style. Its dry wine is R de Rieussec."),
("rabaud-promis", "Château Rabaud-Promis", "Premier Cru Classé (1855)", "Sauternes",
 "The old Rabaud estate in Bommes was ranked as one in 1855, divided in 1903 into Rabaud-Promis and Sigalas-Rabaud, reunited in 1929 and divided again in 1952. Rabaud-Promis has been owned by the Déjean family since 1981."),
("sigalas-rabaud", "Château Sigalas Rabaud", "Premier Cru Classé (1855)", "Sauternes",
 "The smaller half of the old Rabaud estate, on a gravel slope in Bommes facing north-west. Owned by the de Lambert des Granges family, descendants of the Marquis de Sigalas, it makes delicate, pure Sauternes and was among the first to make a sulphite-free sweet wine."),
("de-myrat", "Château de Myrat", "Deuxième Cru Classé (1855)", "Barsac",
 "The de Pontac family, owners since the nineteenth century, pulled up the vines in 1976 when Sauternes could not be sold. Two of the family sons replanted in 1988, and the estate returned to production in the 1990s."),
("doisy-daene", "Château Doisy-Daëne", "Deuxième Cru Classé (1855)", "Barsac",
 "Part of the original Doisy estate, owned by the Dubourdieu family since 1924. Denis Dubourdieu, the great white-wine scientist of the University of Bordeaux, worked here; his sons now run it. Its L'Extravagant, made in tiny quantities from the richest berries, is one of the most concentrated sweet wines of Bordeaux."),
("doisy-dubroca", "Château Doisy-Dubroca", "Deuxième Cru Classé (1855)", "Barsac",
 "The smallest of the three Doisy estates, a few hectares of old Sémillon. For many years it was owned by the Lurton family and made by the team at Climens."),
("doisy-vedrines", "Château Doisy-Védrines", "Deuxième Cru Classé (1855)", "Barsac",
 "The largest of the three Doisy estates and the original seat of the family, owned by the Castéja family since 1840. It makes rich, long-lived Barsac."),
("d-arche", "Château d'Arche", "Deuxième Cru Classé (1855)", "Sauternes",
 "A seventeenth-century château on a gravel hill in Sauternes, named after the Comte d'Arche, an eighteenth-century owner who built up the estate. It makes rich, classic Sauternes with a high share of Sémillon and now hosts a small hotel among the vines, a rare chance to sleep in the heart of the Sauternais."),
("filhot", "Château Filhot", "Deuxième Cru Classé (1855)", "Sauternes",
 "A large estate in the south of Sauternes with an elegant château built in the early nineteenth century and a park. Owned by the Lur-Saluces family for a long time, it now belongs to the Vaucelles family. The wines are lighter than most, with a good share of Sauvignon Blanc."),
("broustet", "Château Broustet", "Deuxième Cru Classé (1855)", "Barsac",
 "A small Barsac estate on the limestone plateau beside the road to Langon, with vineyards on red sand and clay over limestone. Its wines are lighter and more citrus-toned than the Sauternes heavyweights, a good introduction to the Barsac style."),
("nairac", "Château Nairac", "Deuxième Cru Classé (1855)", "Barsac",
 "An elegant château built in 1776 for Élysée Nairac, a Protestant merchant from a family of shipowners, by an architect from the circle of Victor Louis. The Heeter-Tari family revived the estate from 1971 and makes concentrated, oak-aged Barsac."),
("caillou", "Château Caillou", "Deuxième Cru Classé (1855)", "Barsac",
 "A small estate with a neo-Gothic château on the limestone of Barsac, run by the Bravo family. Caillou means pebble. Its wines are fresh and floral."),
("suau", "Château Suau", "Deuxième Cru Classé (1855)", "Barsac",
 "One of the least-known classed growths, a small Barsac vineyard of a few hectares close to the Garonne. Not to be confused with the Château Suau that makes red and white Bordeaux at Capian, across the river.",
 None),
("de-malle", "Château de Malle", "Deuxième Cru Classé (1855)", "Sauternes",
 "A seventeenth-century château with Italian-style gardens and statues, classified as a historic monument, in Preignac. It has belonged to the same family since its construction, now the Bournazel line. It also makes red and dry white Graves."),
("romer", "Château Romer", "Deuxième Cru Classé (1855)", "Sauternes",
 "The small half of the old Romer estate in Fargues, owned by the Farges family. After decades of being leased, the family took back control in 2002, and the wine has regained its place.",
 None),
("romer-du-hayot", "Château Romer du Hayot", "Deuxième Cru Classé (1855)", "Sauternes",
 "The other part of the old Romer estate, in Fargues, run by the du Hayot family since the 1970s. It makes light, fresh, approachable Sauternes."),
("lamothe", "Château Lamothe", "Deuxième Cru Classé (1855)", "Sauternes",
 "In 1961 the old Lamothe estate on a ridge south of Sauternes village was split between two families. Lamothe, run by the Despujols family, is the smaller half. Its steep slope of gravel over clay drains quickly and gives a fresh, mid-weight style of Sauternes."),
("lamothe-guignard", "Château Lamothe Guignard", "Deuxième Cru Classé (1855)", "Sauternes",
 "The larger part of the old Lamothe estate, owned by the Guignard family since 1981, on a ridge of gravel and clay near Sauternes village. The Guignards brought it back to form with stricter tries and better barrels, and it is now one of the reliable values among the Deuxièmes Crus."),
]
for k, n, c, a, t, *p in SB:
    if k == 'suau':
        add(k, n, "chateau", c, a, t, lat=44.5845, lon=-0.3415, q='approx')
    elif k in ('romer', 'romer-du-hayot', 'doisy-dubroca', 'doisy-daene', 'doisy-vedrines'):
        add(k, n, "chateau", c, a, t, q='approx')
    else:
        add(k, n, "chateau", c, a, t)

# ---------------- Graves classification ----------------
GR = [
("la-mission-haut-brion", "Château La Mission Haut-Brion", "Cru Classé de Graves (1959, red; white since the 2009 absorption of Laville Haut-Brion)", "Pessac-Léognan",
 "Facing Haut-Brion across the Avenue Jean Jaurès, La Mission was owned from 1682 to the Revolution by the Lazarist priests of the Congregation of the Mission. The Woltner family made it famous in the twentieth century, and Domaine Clarence Dillon (Haut-Brion's owner) bought it in 1983. It absorbed La Tour Haut-Brion (red) in 2006 and Laville Haut-Brion (white) in 2009, whose wine is now La Mission Haut-Brion Blanc. The red is denser and more muscular than Haut-Brion."),
("pape-clement", "Château Pape Clément", "Cru Classé de Graves (1959, red)", "Pessac-Léognan",
 "Bertrand de Goth, archbishop of Bordeaux, received this vineyard in 1299; in 1305 he became Pope Clement V, the first Avignon pope, and gave the estate to the archdiocese. It is one of the oldest named vineyards in Bordeaux. Bernard Magrez has run it since the 1980s and made it a rich, modern-style Pessac-Léognan."),
("smith-haut-lafitte", "Château Smith Haut Lafitte", "Cru Classé de Graves (1959, red)", "Pessac-Léognan",
 "A Scottish merchant, George Smith, added his name in the eighteenth century. Daniel and Florence Cathiard, both former ski champions, bought it in 1990, made it one of the best estates in the appellation and created Les Sources de Caudalie hotel and spa; their daughter founded Caudalie cosmetics using grape-seed polyphenols. Its white, though unclassified, is among the best of Bordeaux."),
("domaine-de-chevalier", "Domaine de Chevalier", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "A vineyard in a forest clearing in Léognan, exposed to spring frost because cold air pools among the pines. Olivier Bernard's family bought it in 1983. Its white, Sauvignon Blanc and Sémillon fermented in barrel, is one of the longest-lived dry whites in France and is often best after 15 years."),
("haut-bailly", "Château Haut-Bailly", "Cru Classé de Graves (1959, red)", "Pessac-Léognan",
 "Red only, on a gravel hill in Léognan. It keeps a block of vines more than a century old, with several varieties planted together in the old way. American banker Robert Wilmers bought it in 1998 and kept Véronique Sanders, granddaughter of a previous owner, as director. The wine is famous for silky elegance."),
("carbonnieux", "Château Carbonnieux", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "One of the oldest and largest estates of the Graves, run by Benedictine monks of Sainte-Croix in the eighteenth century. A popular story says the monks sold their white wine to the Ottoman court as 'mineral water of Carbonnieux' to get around the ban on alcohol. The Perrin family has owned it since 1956."),
("malartic-lagraviere", "Château Malartic-Lagravière", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "Named after Count Hippolyte de Maurès de Malartic, an eighteenth-century admiral, whose ship is on the label. Belgian businessman Alfred-Alexandre Bonnie bought it in 1997 and rebuilt the cellars; the estate is now one of the most reliable in Léognan."),
("de-fieuzal", "Château de Fieuzal", "Cru Classé de Graves (1959, red)", "Pessac-Léognan",
 "Classified only for red, though its barrel-fermented white made it famous in the 1980s, when Gérard Gribelin showed how good modern white Graves could be. The estate, on gravel in Léognan, has been owned by the Irish Quinn family since 2001, and both colours remain excellent."),
("olivier", "Château Olivier", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "A moated castle with a twelfth-century keep in a hunting estate in Léognan, owned by the de Bethmann family since 1886. The Black Prince is said to have hunted here. The estate has improved greatly since the 2000s."),
("bouscaut", "Château Bouscaut", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "In Cadaujac, close to the Garonne, owned by the Lurton family since 1979 and now run by Sophie Lurton. Its clay and limestone suit Merlot more than most Pessac-Léognan."),
("latour-martillac", "Château Latour-Martillac", "Cru Classé de Graves (1959, red and white)", "Pessac-Léognan",
 "Named after a tower, the remains of a twelfth-century fort, in Martillac. The Kressmann family, Bordeaux négociants, have owned it since 1930. Some white vines date from the 1880s."),
("couhins", "Château Couhins", "Cru Classé de Graves (1959, white)", "Pessac-Léognan",
 "Owned since 1968 by France's national agricultural research institute (INRA, now INRAE), which uses it as an experimental vineyard and also sells its classified white. A rare case of a state-owned classed growth."),
("couhins-lurton", "Château Couhins-Lurton", "Cru Classé de Graves (1959, white)", "Pessac-Léognan",
 "A small part of the old Couhins estate bought by André Lurton in 1967. Its classified white is pure Sauvignon Blanc, barrel-fermented, and ages well."),
]
for k, n, c, a, t in GR:
    add(k, n, "chateau", c, a, t, q='approx' if k == 'couhins-lurton' else None)

# ---------------- Saint-Émilion ----------------
SE = [
("pavie", "Château Pavie", "Premier Grand Cru Classé A (2012, 2022)", "Saint-Émilion Grand Cru",
 "Pavie's vines climb the south-facing côtes from the foot of the slope to the limestone plateau, giving a mix of clay, limestone and sand. Gérard Perse, a former supermarket owner, bought it in 1998 and made it a symbol of the ripe, concentrated style, which divided critics in the early 2000s. It was promoted to A in 2012 and confirmed in 2022, when it became one of only two A estates. A palatial new winery opened in 2013."),
("figeac", "Château Figeac", "Premier Grand Cru Classé A (2022)", "Saint-Émilion Grand Cru",
 "Figeac sits on three gravel croupes near the Pomerol border, sharing the gravel island with Cheval Blanc. Unusually for the right bank, it plants about a third each of Cabernet Sauvignon, Cabernet Franc and Merlot, so its wine is more Médoc-like in structure. Thierry Manoncourt ran it for 60 years; after decades of campaigning the family won promotion to A in 2022, the only estate raised to the top rank that year. A new underground cellar opened in 2021."),
("ausone", "Château Ausone", "Withdrew from the classification in 2021 (formerly Premier Grand Cru Classé A)", "Saint-Émilion Grand Cru",
 "Named after the fourth-century Roman poet Ausonius, who had a villa near Bordeaux, Ausone is a tiny estate of about 7 ha on the edge of the limestone plateau, facing south-east above the town. Its cellars are carved into the rock. The Vauthier family has owned it since the nineteenth century; Alain Vauthier and his daughter Pauline make a dense, mineral wine with a high share of Cabernet Franc. Ausone left the classification in 2021 in protest at its criteria."),
("cheval-blanc", "Château Cheval Blanc", "Withdrew from the classification in 2021 (formerly Premier Grand Cru Classé A)", "Saint-Émilion Grand Cru",
 "On gravel and clay right on the Pomerol border, Cheval Blanc is unusual for its high proportion of Cabernet Franc, often more than half the blend. Its 1947, a heavy, almost port-like wine from a hot year, is often called the greatest Bordeaux of the twentieth century. Owned by Bernard Arnault and the late Albert Frère since 1998. Christian de Portzamparc designed the wave-shaped winery opened in 2011. Cheval Blanc withdrew from the classification in 2021."),
("angelus", "Château Angélus", "Withdrew from the classification in 2022 (formerly Premier Grand Cru Classé A)", "Saint-Émilion Grand Cru",
 "The name comes from the Angelus bells, which could be heard from three churches in the vineyard; a bell is on the label, and the estate's tower plays a carillon. Owned by the de Boüard de Laforest family since 1909, it was promoted to A in 2012. In January 2022 it withdrew from the classification, after a court ruling against co-owner Hubert de Boüard over his role in the 2012 ranking. Stéphanie de Boüard-Rivoal now runs it."),
("beau-sejour-becot", "Château Beau-Séjour Bécot", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "On the limestone plateau west of the town, it was demoted in 1986 for including vines from outside its classified area and promoted back in 1996, a story that shows how seriously the classification can be taken. The Bécot family has owned it since 1969."),
("beausejour", "Château Beauséjour", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "Owned by the Duffau-Lagarrosse family for more than 150 years, this small estate on the plateau and côtes west of the town was sold in 2021 to Joséphine Duffau-Lagarrosse and the Courtin family (Clarins), after a public family dispute. Since then it has dropped 'Duffau-Lagarrosse' from its label."),
("belair-monange", "Château Bélair-Monange", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "On the edge of the limestone plateau next to Ausone, with quarried cellars beneath. The Moueix family bought Bélair in 2008, added Monange (a family name) and merged neighbouring Magdelaine in 2012. The family has since rebuilt the winery. The wine is taut and mineral."),
("canon", "Château Canon", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "Named after Jacques Kanon, an eighteenth-century privateer. The Wertheimer family (Chanel) bought it in 1996 and replanted much of the vineyard after the cellars were found contaminated with TCA; they later absorbed neighbouring Matras and Berliquet. Canon is a pure, limestone-driven wine with a walled clos on the plateau."),
("canon-la-gaffeliere", "Château Canon-la-Gaffelière", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "At the foot of the côtes below the town, owned by Stephan von Neipperg since 1971. He was among the first in Saint-Émilion to farm organically, and his success at this sandy-clay site helped make the 'modern' right bank style. Promoted to B in 2012."),
("larcis-ducasse", "Château Larcis Ducasse", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "On the terraced south-facing côtes of Saint-Laurent-des-Combes, east of the town, beside Pavie. Its limestone terraces face the sun all day. Owned by the Gratiot-Attmane family, it was promoted to B in 2012 under the management of Nicolas Thienpont."),
("pavie-macquin", "Château Pavie Macquin", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "Named after Albert Macquin, who was a pioneer in grafting vines onto American rootstock after phylloxera in the late nineteenth century. The estate is on the limestone plateau above Pavie. Promoted to B in 2006, confirmed since."),
("troplong-mondot", "Château Troplong Mondot", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "On the highest point of Saint-Émilion, about 110 m, its water tower is a local landmark. Raymond Troplong expanded the estate in the nineteenth century. The insurer SCOR bought it in 2017, and the wine has moved from a powerful style to fresher, earlier picking."),
("trottevieille", "Château Trotte Vieille", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "On the limestone plateau east of the town, owned by the Castéja family since 1949. Its name is said to come from an old woman who 'trotted' out to meet travellers on the road. It keeps a small plot of pre-phylloxera Cabernet Franc."),
("valandraud", "Château Valandraud", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "The first 'garage wine': Jean-Luc Thunevin and Murielle Andraud made their first vintage in 1991 from a few rows in a garage in Saint-Émilion town. Its rise from a garage to Premier Grand Cru Classé B in 2012 is a great Bordeaux story. The estate is now based in Saint-Étienne-de-Lisse."),
("clos-fourtet", "Clos Fourtet", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "Right at the gates of the medieval town on the limestone plateau, with a huge network of old quarries beneath it used as cellars. The name may come from a small fort (fortet) that defended the town. The Cuvelier family has owned it since 2001."),
("la-mondotte", "La Mondotte", "Premier Grand Cru Classé B (2022)", "Saint-Émilion Grand Cru",
 "A small vineyard of under 5 ha on the limestone plateau of Saint-Laurent-des-Combes, owned by Stephan von Neipperg. In 1996 he made it an independent wine; it became a cult 'garage' wine and was promoted to B in 2012."),
("la-gaffeliere", "Château La Gaffelière", "Withdrew from the classification in 2022 (formerly Premier Grand Cru Classé B)", "Saint-Émilion Grand Cru",
 "At the foot of the côtes below Ausone, where a Gallo-Roman mosaic with a vine motif was found. Owned by the Malet Roquefort family for more than three centuries, it withdrew from the classification in 2022."),
("tertre-roteboeuf", "Château Tertre Rôteboeuf", "Saint-Émilion Grand Cru (never classified)", "Saint-Émilion Grand Cru",
 "François Mitjavile's small amphitheatre of vines on the south-facing côtes of Saint-Laurent-des-Combes. The name means the hill where the oxen belched, because ploughing it was so hard. Mitjavile never applied for classification, yet his late-picked, voluptuous wine sells above many Premiers Grands Crus Classés."),
("saint-emilion-monolithe", "Monolithic Church of Saint-Émilion", "UNESCO World Heritage (Jurisdiction of Saint-Émilion, 1999)", "Saint-Émilion Grand Cru",
 "Carved out of the limestone in the eleventh and twelfth centuries below a bell tower that rises from the plateau, it is the largest underground church in Europe. It stands above the cave where the Breton monk Émilion lived in the eighth century. The quarries that run under the town and its vineyards supplied stone for Bordeaux and now age wine. The church is the symbol of the UNESCO-listed Jurisdiction of Saint-Émilion, the first vineyard landscape on the World Heritage list."),
]
for k, n, c, a, t in SE:
    kind = "historic" if k == 'saint-emilion-monolithe' else "chateau"
    q = 'approx' if k in ('belair-monange', 'tertre-roteboeuf', 'pavie-macquin', 'trottevieille', 'la-mondotte') else None
    add(k, n, kind, c, a, t, q=q)

# ---------------- Pomerol & Fronsac ----------------
PO = [
("petrus", "Petrus", "Pomerol (unclassified)", "Pomerol",
 "The most famous wine of the right bank, from about 11.5 ha on the highest part of the Pomerol plateau, where a lens of blue-grey clay rises to the surface. The clay swells in wet weather and shrinks in drought, feeding the vines slowly. The wine is almost pure Merlot. Madame Loubat, who owned it from 1925 to 1961, made it a luxury name; the Moueix family took over, and Jean-François Moueix's family owns it today. Petrus spells its name without an accent and without 'Château'."),
("le-pin", "Château Le Pin", "Pomerol (unclassified)", "Pomerol",
 "The original Bordeaux micro-cuvée: Jacques Thienpont bought just over 1 ha with a lone pine tree in 1979 and made wine in a cellar under a farmhouse. Le Pin is now about 2.8 ha, Merlot on gravel over clay, and costs more than Petrus at auction. A new cellar designed by Paul Robbrecht opened in 2011."),
("lafleur", "Château Lafleur", "Pomerol (unclassified)", "Pomerol",
 "A small estate of about 4.5 ha next to Petrus with a higher share of Cabernet Franc, giving a fragrant, intense, long-lived wine. The Guinaudeau family has run it since 1985, when Jacques and Sylvie Guinaudeau took over from the Robin family; their son Baptiste and his wife Julie now manage it."),
("vieux-chateau-certan", "Vieux Château Certan", "Pomerol (unclassified)", "Pomerol",
 "One of the oldest estates in Pomerol, with records going back to the sixteenth century. The Belgian Thienpont family bought it in 1924; Alexandre Thienpont and his son Guillaume make a wine with a high proportion of Cabernet Franc and some Cabernet Sauvignon. It is the most Médoc-like and perfumed of the great Pomerols."),
("l-eglise-clinet", "Château L'Église-Clinet", "Pomerol (unclassified)", "Pomerol",
 "A small estate around Pomerol's church on gravel and clay. Denis Durantou, who ran it from 1983 until his death in 2020, made it one of the best Pomerols with old vines, including a plot of ungrafted pre-phylloxera Merlot and Cabernet Franc. His daughters now run it."),
("la-conseillante", "Château La Conseillante", "Pomerol (unclassified)", "Pomerol",
 "Owned by the Nicolas family since 1871, on the border with Saint-Émilion and Cheval Blanc. Its silver and violet capsule echoes the violet perfume of its wine, among the most silky and elegant in Pomerol."),
("l-evangile", "Château L'Évangile", "Pomerol (unclassified)", "Pomerol",
 "Next to Petrus and Cheval Blanc, on gravel and clay. The Rothschilds of Lafite have owned it since 1990 and built a new winery in 2004. Rich, dense and long-lived Pomerol."),
("trotanoy", "Château Trotanoy", "Pomerol (unclassified)", "Pomerol",
 "Owned by the Moueix family since 1953, on a slope of dense clay and gravel west of Pomerol church. The name comes from 'trop ennuie', too troublesome, because its clay was so hard to plough. It is one of the most powerful Pomerols.",),
("la-fleur-petrus", "Château La Fleur-Pétrus", "Pomerol (unclassified)", "Pomerol",
 "Owned by the Moueix family since 1950, between Petrus and Lafleur on gravel and clay. It added parcels from Le Gay and has grown in quality, with a fresh, floral style."),
("clinet", "Château Clinet", "Pomerol (unclassified)", "Pomerol",
 "On the high gravel of the Pomerol plateau. Michel Rolland's early work here in the 1980s made it a model of ripe, opulent Merlot. The Laborde family has owned it since 1998."),
("fronsac-tertre", "Château de la Dauphine", "Fronsac", "Fronsac",
 "An eighteenth-century château on the Fronsac hillside above the Dordogne, said to be named after the Dauphine Marie-Josèphe de Saxe, who visited. Moueix once owned it; the Labrune family has run it since 2015 with organic farming. It shows Fronsac's fresh, mineral side."),
]
for k, n, c, a, t, *p in PO:
    q = 'approx' if k in ('le-pin', 'trotanoy', 'la-fleur-petrus') else None
    add(k, n, "chateau", c, a, t, q=q)

# ---------------- Crus Bourgeois Exceptionnels 2025 ----------------
CB = [
("cb-la-cardonne", "Château La Cardonne", "Médoc", "In Blaignan-Prignac, once owned by the Rothschilds of Lafite (1973 to 1990). Its clay-limestone and gravel hill gives fresh, structured Médoc. Ranked Exceptionnel in 2025."),
("cb-castera", "Château Castéra", "Médoc", "A medieval castle in Saint-Germain-d'Esteuil which, according to local tradition, was burnt by the Black Prince's troops in the fourteenth century and later rebuilt. Its gravel and clay-limestone soils make firm, fresh Médoc. Ranked Exceptionnel in 2025."),
("cb-laujac", "Château Laujac", "Médoc", "A large estate in Bégadan in the northern Médoc, owned by the Cruse négociant family for more than a century. Its gravel ridge gives a classic, firm Médoc. Ranked Exceptionnel in 2025."),
("cb-paloumey", "Château Paloumey", "Haut-Médoc", "In Ludon, close to La Lagune. Martine Cazeneuve revived the estate from 1989, replanting the gravel vineyard and building new cellars. The wine is ripe and supple, with the soft texture typical of the sandy gravels of the southern Haut-Médoc. Ranked Exceptionnel in 2025."),
("cb-reysson", "Château Reysson", "Haut-Médoc", "In Vertheuil, north-west of Saint-Estèphe, owned by the Dourthe group. A Merlot-dominant Haut-Médoc from clay-limestone, polished and generous rather than austere, and one of the Haut-Médoc estates ranked Exceptionnel in the 2025 classification."),
("cb-malescasse", "Château Malescasse", "Haut-Médoc", "In Lamarque, between Margaux and Saint-Julien, on gravel ridges near the estuary ferry to Blaye. Owned since 2012 by businessman Philippe Austruy, who invested heavily in the cellar and vineyard. It was ranked Exceptionnel in both 2020 and 2025."),
("cb-de-malleret", "Château de Malleret", "Haut-Médoc", "A historic estate in Le Pian-Médoc on the edge of the city, with gravel soils close to La Lagune and a large wooded park. The wine is supple, Cabernet-led southern Haut-Médoc. Ranked Exceptionnel in 2025."),
("cb-du-taillan", "Château du Taillan", "Haut-Médoc", "A seventeenth-century château in Le Taillan-Médoc, owned by the Cruse family since 1896. Its white wine, La Dame Blanche, is sold as Bordeaux. Exceptionnel in 2020 and 2025."),
("cb-reverdi", "Château Reverdi", "Listrac-Médoc", "A family estate in Listrac, on the clay-limestone and gravel of the Médoc's highest commune, at the edge of the pine forest. Its fresh, firm reds show the cooler side of the Médoc. It is the only Listrac estate among the fourteen Exceptionnels of 2025."),
("cb-d-arsac", "Château d'Arsac", "Margaux", "A large estate in Arsac on the western edge of the Margaux appellation, owned by Philippe Raoux, known for contemporary art in its vineyards, including a giant blue sculpture. Exceptionnel in 2020 and 2025."),
("cb-mongravey", "Château Mongravey", "Margaux", "A small family estate in Arsac, on the western edge of the Margaux appellation, run by Régis Bernaleau and his family. It makes ripe, structured Margaux from gravel soils, at a fraction of classed-growth prices. Ranked Exceptionnel in 2025."),
("cb-paveil-de-luze", "Château Paveil de Luze", "Margaux", "Owned by the de Luze family, Bordeaux négociants, since 1862, in Soussans in the north of the Margaux appellation. Its gravel and clay soils give elegant, fresh, fairly priced Margaux. Ranked Exceptionnel in both 2020 and 2025."),
("cb-le-crock", "Château Le Crock", "Saint-Estèphe", "An early-nineteenth-century château in Saint-Estèphe, owned by the Cuvelier family (also of Léoville Poyferré) since 1903. It makes firm, savoury, long-lived Saint-Estèphe. Ranked Exceptionnel in both 2020 and 2025."),
("cb-lafitte-carcasset", "Château Lafitte Carcasset", "Saint-Estèphe", "A Saint-Estèphe estate north of the village, unrelated to Lafite Rothschild despite the name, which comes from an older owner. Its gravel and clay soils give a firm, classic Saint-Estèphe that ages well. Ranked Exceptionnel in 2025."),
]
for k, n, a, t in CB:
    kw = {}
    if k == 'cb-lafitte-carcasset': kw = dict(lat=45.2700, lon=-0.7820, q='approx')
    elif k in ('cb-reysson', 'cb-le-crock', 'cb-du-taillan'): kw = dict(q='approx')
    add(k, n, "chateau", "Cru Bourgeois Exceptionnel (2025)", a, t, **kw)

